<script setup lang="ts">import{onMounted,ref}from'vue';import http from'../api/http';const rows=ref<any[]>([]),total=ref(0),dialog=ref(false),form=ref<any>({materialCode:'',materialName:'',materialType:'RAW',baseUnitCode:'EA'});async function load(){const{data}=await http.get('/mdm/materials',{params:{page:1,size:20}});rows.value=data.data.content;total.value=data.data.totalElements}async function create(){await http.post('/mdm/materials',form.value);dialog.value=false;form.value={materialCode:'',materialName:'',materialType:'RAW',baseUnitCode:'EA'};load()}async function submit(r:any){await http.post(`/mdm/materials/${r.id}/submit`);load()}onMounted(load)</script>
<template><el-card><template #header><span>物料主数据</span><el-button type="primary" style="float:right" @click="dialog=true">新建物料</el-button></template><el-table :data="rows"><el-table-column prop="materialCode" label="物料编码"/><el-table-column prop="materialName" label="物料名称"/><el-table-column prop="materialType" label="类别"/><el-table-column prop="status" label="状态"/><el-table-column prop="versionNo" label="版本"/><el-table-column label="操作"><template #default="{row}"><el-button v-if="row.status==='DRAFT'||row.status==='REJECTED'" size="small" @click="submit(row)">提交审批</el-button></template></el-table-column></el-table><p>共 {{total}} 条</p></el-card><el-dialog v-model="dialog" title="新建物料"><el-form label-width="88px"><el-form-item label="物料编码"><el-input v-model="form.materialCode"/></el-form-item><el-form-item label="物料名称"><el-input v-model="form.materialName"/></el-form-item><el-form-item label="类别"><el-select v-model="form.materialType"><el-option label="原材料" value="RAW"/><el-option label="半成品" value="SEMI"/><el-option label="成品" value="FINISHED"/></el-select></el-form-item><el-form-item label="基本单位"><el-input v-model="form.baseUnitCode"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="create">保存草稿</el-button></template></el-dialog></template>
